// (ios/.../NotificationRecords.swift serializedNotificationData).
import crypto from 'node:crypto';
import fs from 'node:fs';
import http2 from 'node:http2';
import { signJwt } from './jwt.mjs';

export const APNS_PRODUCTION = 'https://api.push.apple.com';
export const APNS_SANDBOX = 'https://api.sandbox.push.apple.com';
const JWT_TTL_MS = 50 * 60_000; // Apple: refresh no more often than every 20 min, never older than 60 min

/** ES256 provider token. */
export function apnsJwt(key, keyId, teamId, nowSec = Math.floor(Date.now() / 1000)) {
  return signJwt({ alg: 'ES256', kid: keyId }, { iss: teamId, iat: nowSec }, key);
}

export function apnsPayload(n) {
  const aps = { alert: { title: n.title, body: n.body }, 'thread-id': n.threadId ?? undefined };
  if (n.quiet) aps['interruption-level'] = 'passive';
  else aps.sound = 'default';
  return { aps, body: n.data ?? {} };
}

export const isHexToken = (t) => typeof t === 'string' && /^[0-9a-fA-F]{32,200}$/.test(t);

/**
 * @param {{key: string|crypto.KeyObject, keyId: string, teamId: string, topic: string,
 *   origins?: {production: string, sandbox: string}, timeoutMs?: number}} cfg
 *   key = PEM text of the .p8 file or a path to it.
 */
export function createApnsSender(cfg) {
  if (!cfg.keyId || !cfg.teamId || !cfg.topic) throw new Error('APNs: keyId, teamId and topic are required');
  const key =
    typeof cfg.key === 'string' ? crypto.createPrivateKey(cfg.key.includes('BEGIN') ? cfg.key : fs.readFileSync(cfg.key, 'utf8')) : cfg.key;
  const origins = cfg.origins ?? { production: APNS_PRODUCTION, sandbox: APNS_SANDBOX };
  const sessions = new Map(); // origin -> ClientHttp2Session
  let jwt = null;

  function token() {
    if (!jwt || Date.now() - jwt.at > JWT_TTL_MS) jwt = { value: apnsJwt(key, cfg.keyId, cfg.teamId), at: Date.now() };
    return jwt.value;
  }

  function session(origin) {
    let s = sessions.get(origin);
    if (s && !s.closed && !s.destroyed) return s;
    s = http2.connect(origin);
    s.on('error', () => sessions.delete(origin));
    s.on('close', () => sessions.delete(origin));
    s.on('goaway', () => sessions.delete(origin));
    s.setTimeout(10 * 60_000, () => s.close());
    s.unref?.();
    sessions.set(origin, s);
    return s;
  }

  function post(origin, deviceToken, n) {
    return new Promise((resolve) => {
      let s;
      try {
        s = session(origin);
      } catch (e) {
        return resolve({ ok: false, status: 0, error: 'apns connect' });
      }
      const headers = {
        ':method': 'POST',
        ':path': `/3/device/${deviceToken}`,
        authorization: `bearer ${token()}`,
        'apns-topic': cfg.topic,
        'apns-push-type': 'alert',
        'apns-priority': n.quiet ? '5' : '10',
        'apns-expiration': String(Math.floor(Date.now() / 1000) + (n.ttl ?? 86400)),
        'content-type': 'application/json',
      };
      if (n.collapseKey) headers['apns-collapse-id'] = n.collapseKey.slice(0, 64);
      const req = s.request(headers);
      let status = 0;
      let data = '';
      const timer = setTimeout(() => req.close(http2.constants.NGHTTP2_CANCEL), cfg.timeoutMs ?? 15000);
      req.setEncoding('utf8');
      req.on('response', (h) => (status = Number(h[':status'])));
      req.on('data', (c) => (data += c));
      req.on('error', () => {
        clearTimeout(timer);
        resolve({ ok: false, status: 0, error: 'apns network' });
      });
      req.on('close', () => {
        clearTimeout(timer);
        if (!status) return resolve({ ok: false, status: 0, error: 'apns closed' });
        if (status === 200) return resolve({ ok: true, status });
        let reason = '';
        try {
          reason = JSON.parse(data).reason ?? '';
        } catch {
          /* empty body */
        }
        resolve({ ok: false, status, reason, error: `apns ${status} ${reason}`.trim() });
      });
      req.end(JSON.stringify(apnsPayload(n)));
    });
  }

  return {
    kind: 'apns',
    /**
     * Send to one device. `environment` = 'production' | 'sandbox' | undefined (unknown: production first,
     * BadDeviceToken -> sandbox; the result reports the environment that worked so the store can remember it).
     */
    async send(deviceToken, n, environment) {
      if (!isHexToken(deviceToken)) return { ok: false, status: 400, gone: true, error: 'apns invalid token' };
      const order = environment === 'sandbox' ? ['sandbox'] : environment === 'production' ? ['production'] : ['production', 'sandbox'];
      let last = null;
      for (const env of order) {
        const r = await post(origins[env], deviceToken, n);
        if (r.ok) return { ...r, environment: env };
        last = { ...r, environment: env };
        if (!(r.status === 400 && r.reason === 'BadDeviceToken')) break;
      }
      const gone = last.status === 410 || last.reason === 'Unregistered' || last.reason === 'BadDeviceToken' || last.reason === 'DeviceTokenNotForTopic';
      return { ...last, gone };
    },
    close() {
      for (const s of sessions.values()) s.close();
      sessions.clear();
    },
  };
}
